contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(true);
        require(address(this).balance >= a);
        // fund C by another account path? Not possible; instead deposit then withdraw to clear credit,
        // so this account has zero credit but C may hold other effects.
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == beforeC && address(this).balance == beforeThis);
    }
    receive() external payable {}
}

