// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        vm.assume(address(this).balance >= a);
        try c.deposit{value: a}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == beforeC && address(this).balance == beforeThis);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
